class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def isValidBST(self, root):
        vals = []
        def inorder(node):
            if not node: return
            inorder(node.left); vals.append(node.val); inorder(node.right)
        inorder(root)
        return all(vals[i] < vals[i + 1] for i in range(len(vals) - 1))

